package dev.jarofcucumbers.prscraft.client;
import dev.jarofcucumbers.prscraft.*;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.nbt.*;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.neoforged.neoforge.network.PacketDistributor;
public final class NotebookScreen extends PanelScreen{
    private CompoundTag data;private int index,slot;private EditBox title;private MessageTextBox notes;private String error="";
    public NotebookScreen(CompoundTag data){super(Component.translatable("item.prscraft.research_notebook"),920,640);this.data=data;slot=data.getInt("slot");index=Math.max(0,data.getList("experiments",10).size()-1);}
    public void receive(CompoundTag next){boolean added=next.getList("experiments",10).size()>data.getList("experiments",10).size();data=next;error=next.getString("error");if(added)index=data.getList("experiments",10).size()-1;index=Math.max(0,Math.min(index,data.getList("experiments",10).size()-1));clearWidgets();title=null;notes=null;build();}
    private CompoundTag entry(){var list=data.getList("experiments",10);return index<list.size()?list.getCompound(index):new CompoundTag();}
    private void request(String action){var target=minecraft.hitResult instanceof net.minecraft.world.phys.BlockHitResult hit?hit.getBlockPos():minecraft.player.blockPosition();PacketDistributor.sendToServer(new NotebookNetwork.Request(slot,index,action,title==null?"":title.getValue(),notes==null?"":notes.getValue(),target,-1));}
    @Override protected void build(){title=field(14,52,566,entry().getString("title"),64,"notebook_title");notes=addRenderableWidget(new MessageTextBox(font,14,116,566,150,tr("notebook_notes"),false));notes.setCharacterLimit(2048);notes.setValue(entry().getString("description"));button(596,52,310,tr("notebook_capture"),b->request("capture"));button(596,98,310,tr("notebook_new"),b->request("new"));button(596,144,310,tr("notebook_save"),b->request("save"));button(596,190,310,tr("notebook_template"),b->request("template"));button(596,236,310,tr("sim_delete"),b->request("remove"));button(596,282,310,tr("message_lab"),b->minecraft.setScreen(new MessageScreen(this,BlockPos.of(entry().getCompound("capture").getLong("device")),capture()))).active=entry().getCompound("capture").getBoolean("dataStream");button(14,594,150,tr("back"),b->onClose());button(178,594,150,Component.literal("←"),b->{saveIfDirty();index=Math.max(0,index-1);clearWidgets();build();});button(342,594,150,Component.literal("→"),b->{saveIfDirty();index=Math.min(Math.max(0,data.getList("experiments",10).size()-1),index+1);clearWidgets();build();});button(506,594,190,tr("oscilloscope"),b->minecraft.setScreen(new PlotScreen(this,capture()))).active=entry().contains("capture");button(710,594,196,tr("spectrum"),b->minecraft.setScreen(new SpectrumScreen(this,capture()))).active=entry().contains("capture");}
    private CompoundTag capture(){var capture=entry().getCompound("capture").copy();capture.putBoolean("recorded",true);capture.putString("captureKind",capture.getString("kind"));capture.putString("kind","recording");return capture;}
    @Override protected void draw(GuiGraphics g){label(g,"notebook_title",14,36);label(g,"notebook_notes",14,94);g.drawString(font,(index+1)+" / "+data.getList("experiments",10).size()+" · max 8",14,288,0xffb8d8dd,false);var capture=entry().getCompound("capture");g.fill(14,316,906,544,0xff0a1420);double[] samples=SignalChain.unpack(capture.getIntArray("received"));double max=1;for(double v:samples)max=Math.max(max,Math.abs(v)*1.1);int last=430;for(int x=0;x<890&&samples.length==512;x++){int y=430-(int)(samples[x*512/890]/max*100);if(x>0)line(g,13+x,last,14+x,y,0xff73dfb5);last=y;}g.drawString(font,"0 s                         T="+fmt(capture.getDouble("span"))+" s · "+capture.getString("units")+" · tick="+entry().getLong("tick"),22,552,0xffa9d2d8,false);String problem=error.isEmpty()?capture.getString("messageError"):error;if(!problem.isEmpty())g.drawString(font,Component.translatable("error.prscraft."+problem),22,574,0xffffb179,false);}
    private void saveIfDirty(){if(entry().contains("title")&&title!=null&&notes!=null&&(!entry().getString("title").equals(title.getValue())||!entry().getString("description").equals(notes.getValue())))request("save");}
    @Override public void onClose(){saveIfDirty();RadioClient.closeDevice(null);}
}
